const $=s=>document.querySelector(s),sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms));
const assert=(v,m)=>{if(!v)throw Error(m);},button=(i,a)=>`[data-deck="${i}"][data-action="${a}"]`;
const click=s=>{assert($(s),'Missing '+s);$(s).click();};
const files=['app.js','engine.js','panels.js','keylock-shadow-live.js','sync-tempo-handoff.js','stem-mixed-activation-harness.js','stem-activation-capture-145.js','vendor/signalsmith-stretch/SignalsmithStretch-open-play-replace.mjs'];
const sha=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(x=>x.toString(16).padStart(2,'0')).join('');
async function identities(){return Object.fromEntries(await Promise.all(files.map(async f=>{const r=await fetch(f,{cache:'no-store'});assert(r.ok,'Missing '+f);return[f,await sha(await r.arrayBuffer())];})));}
async function until(fn,label,ms=20000){const end=performance.now()+ms;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(10);}}
function base64(bytes){let s='';for(let n=0;n<bytes.length;n+=16384)s+=String.fromCharCode(...bytes.subarray(n,n+16384));return btoa(s);}
let app;
async function run(){
 const {engine,state}=app,decks=state.decks.slice(0,2),track=decks[0].track,witnesses=[];let recording,observer,adapter;
 const r={checkpoint:148,startedAt:new Date().toISOString(),scope:'Actual production Play, mixed staged/cold attachStems cancellation/retry and actual immediate Vocal pads. Authored Vocal equals original, other three buffers silent. Per-deck stereo rendered audio; no model inference, musical quality, native/hardware or full parity acceptance.',criteria:{captureSeconds:4,minimum10msRMSRatio:.85,maximumAdjacentJump:.03,maximumNearZeroRunSeconds:.001,nearZeroAbsolute:1e-7,firstMuteWindowStartSeconds:.03,firstMuteWindowEndSeconds:.08,maximumFirstMuteRMS:.0001},errors:[]};
 function capture(){return Promise.all(witnesses.map(w=>new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('PCM capture timeout')),14000);w.port.onmessage=({data})=>{if(data.type==='done'){clearTimeout(timer);resolve(data);}};w.port.postMessage({type:'capture',id:'mixed',frames:Math.round(r.criteria.captureSeconds*engine.ctx.sampleRate)});})));}
 async function retain(packets){return Promise.all(packets.map(async(p,i)=>({deck:Math.floor(i/2),channel:i%2,startFrame:p.startFrame,frames:p.data.length,quanta:p.quanta,errors:p.errors,sha256:await sha(p.data.buffer),base64:base64(new Uint8Array(p.data.buffer))})));}
 $('#mixed-run').disabled=true;
 try{
  r.sourceBefore=await identities();engine.init();engine.audioMonitor.mutePhysical(true);await engine.resume();assert(engine.audioMonitor.snapshot().physicalMuted,'Physical mute');await until(()=>!state.analysis,'Initial analysis');for(const d of state.decks)engine.pause(d);
  for(const unit of state.fx)for(const slot of unit)slot.on=false;engine.configureFX(state.fx,state.fxRoutes||[],state.decks.map(d=>(d.track?.bpm||120)*d.rate),state.fxTempo);
  const sr=44100,original=engine.ctx.createBuffer(2,sr*16,sr);for(let c=0;c<2;c++)for(let n=0;n<original.length;n++)original.getChannelData(c)[n]=.12*Math.sin(2*Math.PI*(c?550:330)*n/sr);
  const stems=[original,...Array.from({length:3},()=>engine.ctx.createBuffer(2,original.length,sr))];r.sampleRate=engine.ctx.sampleRate;r.originalHashes=await Promise.all([0,1].map(c=>sha(original.getChannelData(c).buffer)));
  Object.assign(track,{duration:16,bpm:120,grid:0,gridWarpMarkers:[],gridMarkers:[],analyzed:true});engine.buffers.set(track.id,original);engine.stemBuffers.delete(track.id);
  for(const [i,d]of decks.entries()){Object.assign(d,{track,position:1,rate:1.1,keylock:i===0,keyShift:0,reverse:false,loop:false,slip:false,stemSlip:'off',sync:false,mode:'INT',stems:[true,true,true,true],stemFX:[false,false,false,false]});engine.clearDeckScratchCache(i);engine.mix(i,'level',.5);}
  await engine.ctx.audioWorklet.addModule(new URL('./stem-activation-capture-145.js',import.meta.url));for(let i=0;i<2;i++){const split=engine.ctx.createChannelSplitter(2);engine.nodes[i].monitorTap.connect(split);for(let c=0;c<2;c++){const w=new AudioWorkletNode(engine.ctx,'open-play-stem-activation-145-test',{numberOfInputs:1,numberOfOutputs:1,outputChannelCount:[1],channelCount:1,channelCountMode:'explicit',channelInterpretation:'discrete'});split.connect(w,c);w.connect(engine.ctx.destination);witnesses.push(w);}}
  for(let i=0;i<2;i++){click(button(i,'tab')+'[data-tab="Stems"]');click(button(i,'play'));await until(()=>decks[i].playing&&!decks[i].processing,'Play '+i);}
  const voices=decks.map(d=>engine.voices.get(d.index));adapter=voices[0].liveKeylock;assert(adapter?.reservedStems&&!voices[1].liveKeylock,'Actual mixed live/ordinary owners');r.initialLive=adapter.snapshot();r.anchors=decks.map(d=>({position:d.anchorPosition,when:d.anchorTime,rate:d.rate}));
  await sleep(200);recording=capture();await sleep(200);$('#mixed-status').textContent='Capturing mixed cancellation, retry and first pads…';
  const controller=new AbortController();observer=adapter.onEvent;r.cancel={startedAt:engine.ctx.currentTime,warmupObserved:false};adapter.onEvent=e=>{observer(e);if(e.type==='stem-bank-warming'&&!controller.signal.aborted){r.cancel.warmupObserved=true;r.cancel.abortAt=engine.ctx.currentTime;controller.abort();}};
  try{await engine.attachStems(track,stems,decks,{signal:controller.signal});throw Error('Cancelled attachment resolved');}catch(error){assert(error.name==='AbortError',error.message);r.cancel.error=error.name;}finally{adapter.onEvent=observer;observer=null;}
  r.cancel.finishedAt=engine.ctx.currentTime;r.cancel.sameOwners=decks.map((d,i)=>engine.voices.get(d.index)===voices[i]);r.cancel.cacheAbsent=!engine.stemBuffers.has(track.id);r.cancel.stageCleared=adapter.snapshot().stagedStemBank===null;assert(r.cancel.sameOwners.every(Boolean)&&r.cancel.cacheAbsent&&r.cancel.stageCleared,'Cancelled mixed activation changed audible owners/cache');
  await sleep(200);r.retry={startedAt:engine.ctx.currentTime};await engine.attachStems(track,stems,decks);r.retry.returnedAt=engine.ctx.currentTime;r.retry.sameOwners=decks.map((d,i)=>engine.voices.get(d.index)===voices[i]);r.retry.cachePublished=engine.stemBuffers.get(track.id)===stems;r.retry.live=adapter.snapshot();r.retry.handoffTimes=decks.map(d=>engine.voices.get(d.index).handoffBefore?.until??null);
  assert(r.retry.sameOwners[0]&&!r.retry.sameOwners[1]&&r.retry.cachePublished,'Mixed retry geometry');r.firstPads=[];
  for(let i=0;i<2;i++){const at=engine.ctx.currentTime;click(button(i,'pad')+'[data-pad="0"]');r.firstPads.push({deck:i,at,enabled:[...decks[i].stems]});assert(!decks[i].stems[0]&&decks[i].stems.slice(1).every(Boolean),'Actual Vocal pad '+i);}
  await sleep(300);r.restoreAt=engine.ctx.currentTime;for(let i=0;i<2;i++)click(button(i,'pad')+'[data-pad="0"]');await sleep(300);r.stopAt=engine.ctx.currentTime;for(let i=0;i<2;i++)click(button(i,'play'));await until(()=>decks.every(d=>!d.playing),'Both stopped');
  r.pcm=await retain(await recording);r.originalUnchanged=JSON.stringify(r.originalHashes)===JSON.stringify(await Promise.all([0,1].map(c=>sha(original.getChannelData(c).buffer))));assert(r.originalUnchanged,'Original mutated');r.workflowExecuted=true;
 }catch(error){r.errors.push({message:error.message,stack:error.stack});if(recording&&!r.pcm)try{r.pcm=await retain(await recording);}catch(e){r.errors.push({captureError:e.message});}}
 finally{if(observer&&adapter)adapter.onEvent=observer;for(const d of state.decks)engine.pause(d);for(const w of witnesses){w.disconnect();w.port.close();}r.sourceAfter=await identities();r.sourceStable=JSON.stringify(r.sourceBefore)===JSON.stringify(r.sourceAfter);r.workflowCompleted=!!r.workflowExecuted&&!r.errors.length&&r.sourceStable;r.finishedAt=new Date().toISOString();$('#mixed-original').textContent=JSON.stringify(r);$('#mixed-results').textContent=JSON.stringify({...r,pcm:r.pcm?.map(({base64,...p})=>p)},null,2);$('#mixed-status').textContent=r.workflowCompleted?'Mixed workflow retained; independent first-pad/audio inspection required; stopped':'Failed: '+r.errors.map(e=>e.message).join('; ');}
}
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[0].track,'Actual app');app=window.openPlay;$('#mixed-run').disabled=false;$('#mixed-status').textContent='Ready';}
$('#mixed-run').onclick=()=>run();boot().catch(e=>$('#mixed-status').textContent=e.message);
